-- docs/superpowers/plans/2026-11-18-permissions-server-enforcement.md Fix-C
-- (follow-up to whole-branch review findings C3 and I4 on top of Task 8's
-- 20261212000000_permissions_and_billing_admin_gates.sql).
--
-- C3: Task 8 gated roles_tenant_insert/_update and
-- user_permission_overrides_tenant_insert/_update on staff.permissions via
-- app_has_permission() (Task 1), but never touched either table's DELETE
-- policy. roles_tenant_delete / user_permission_overrides_tenant_delete
-- were still the generic %I_tenant_delete form generated by the
-- tenant_tables loop in 20240601000000_track_base_schema.sql:
--   app_is_super_admin() OR tenant_id = app_current_tenant_id()
-- with no role/permission predicate at all. Confirmed by grepping every
-- migration for both policy names -- no hits besides the base-schema loop
-- (same discipline as Tasks 6-8: these two names were never touched since
-- the generic loop created them). That gap let any staff member DELETE
-- their own restrictive user_permission_overrides row, or delete a custom
-- roles row out from under staff.role_id (ON DELETE SET NULL, falling back
-- to more permissive enum defaults) -- fully bypassing the override and
-- custom-role layers the rest of this plan relies on.
--
-- I4: user_permission_overrides_tenant_insert/_update (Task 8) check
-- tenant_id = app_current_tenant_id() but never verify that the row's
-- staff_id column actually belongs to a staff member of that SAME tenant.
-- app_current_staff_id() (20260910020000_backfill_inventory_fix.sql)
-- resolves purely from the caller's own auth.uid(), so it is inherently
-- tenant-safe on the READ side -- a caller can only ever be resolved to
-- their own staff row. But nothing stopped tenant A's admin from
-- INSERTing/UPDATEing an override row with tenant_id = A but staff_id
-- pointing at a staff member who actually belongs to tenant B -- that row
-- would silently affect tenant B's staff member's permission resolution
-- (app_has_permission's own lookup has no tenant filter; it is only safe
-- because v_staff_id there is always the CALLER's own id). Tenant B could
-- never see or remove the planted row, since their own _tenant_read/
-- _tenant_delete policies filter by tenant_id = B and the row's tenant_id
-- is A.
--
-- Fix:
--   1) roles_tenant_delete / user_permission_overrides_tenant_delete:
--      rebuilt with the same staff.permissions gate as Task 8's
--      INSERT/UPDATE policies on these two tables.
--   2) user_permission_overrides_tenant_insert's WITH CHECK, and
--      user_permission_overrides_tenant_update's USING + WITH CHECK: add
--      an EXISTS (public.staff) condition requiring the row's staff_id to
--      belong to a staff member of the caller's own tenant, alongside
--      (inside the same non-super-admin branch as) the existing
--      tenant_id/staff.permissions check. app_has_permission()'s own
--      internal lookups are left untouched -- they are already tenant-safe
--      on the read side for the reason above; this only closes the
--      WRITE-side gap.
-- =============================================================================

-- -----------------------------------------------------------------------
-- C3: roles / user_permission_overrides DELETE gates
-- -----------------------------------------------------------------------

DROP POLICY IF EXISTS roles_tenant_delete ON public.roles;
CREATE POLICY roles_tenant_delete ON public.roles
  FOR DELETE USING (
    app_is_super_admin()
    OR (tenant_id = app_current_tenant_id() AND app_has_permission('staff.permissions'))
  );

DROP POLICY IF EXISTS user_permission_overrides_tenant_delete ON public.user_permission_overrides;
CREATE POLICY user_permission_overrides_tenant_delete ON public.user_permission_overrides
  FOR DELETE USING (
    app_is_super_admin()
    OR (tenant_id = app_current_tenant_id() AND app_has_permission('staff.permissions'))
  );

-- -----------------------------------------------------------------------
-- I4: user_permission_overrides INSERT/UPDATE cross-tenant staff_id check
-- -----------------------------------------------------------------------

DROP POLICY IF EXISTS user_permission_overrides_tenant_insert ON public.user_permission_overrides;
CREATE POLICY user_permission_overrides_tenant_insert ON public.user_permission_overrides
  FOR INSERT WITH CHECK (
    app_is_super_admin()
    OR (
      tenant_id = app_current_tenant_id()
      AND app_has_permission('staff.permissions')
      AND EXISTS (
        SELECT 1 FROM public.staff s
        WHERE s.id = user_permission_overrides.staff_id
          AND s.tenant_id = app_current_tenant_id()
      )
    )
  );

DROP POLICY IF EXISTS user_permission_overrides_tenant_update ON public.user_permission_overrides;
CREATE POLICY user_permission_overrides_tenant_update ON public.user_permission_overrides
  FOR UPDATE USING (
    app_is_super_admin()
    OR (
      tenant_id = app_current_tenant_id()
      AND app_has_permission('staff.permissions')
      AND EXISTS (
        SELECT 1 FROM public.staff s
        WHERE s.id = user_permission_overrides.staff_id
          AND s.tenant_id = app_current_tenant_id()
      )
    )
  )
  WITH CHECK (
    app_is_super_admin()
    OR (
      tenant_id = app_current_tenant_id()
      AND app_has_permission('staff.permissions')
      AND EXISTS (
        SELECT 1 FROM public.staff s
        WHERE s.id = user_permission_overrides.staff_id
          AND s.tenant_id = app_current_tenant_id()
      )
    )
  );
